"use client";

import { createContext, useContext, type ButtonHTMLAttributes, type HTMLAttributes, type ReactNode } from "react";

type ToggleGroupValue = { value: string[]; type: "single" | "multiple"; change: (value: string) => void };
const ToggleGroupContext = createContext<ToggleGroupValue | null>(null);
export function ToggleGroup({ type = "single", value, onValueChange, className = "", children, ...props }: HTMLAttributes<HTMLDivElement> & { type?: "single" | "multiple"; value: string[]; onValueChange: (value: string[]) => void; children: ReactNode }) { function change(item: string) { if (type === "single") onValueChange(value.includes(item) ? [] : [item]); else onValueChange(value.includes(item) ? value.filter((entry) => entry !== item) : [...value, item]); } return <ToggleGroupContext.Provider value={{ value, type, change }}><div role="group" className={`co-inline-flex co-rounded-md co-border co-border-black/15 co-p-1 ${className}`.trim()} {...props}>{children}</div></ToggleGroupContext.Provider>; }
export function ToggleGroupItem({ value, className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { value: string }) { const group = useContext(ToggleGroupContext); if (!group) throw new Error("ToggleGroupItem requires ToggleGroup."); const pressed = group.value.includes(value); return <button type="button" aria-pressed={pressed} className={`co-h-8 co-rounded co-px-3 co-text-sm focus-visible:co-ring-2 ${pressed ? "co-bg-black co-text-white" : "hover:co-bg-black/5"} ${className}`.trim()} onClick={() => group.change(value)} {...props} />; }
